import React, { useEffect, useState, useMemo } from 'react';
import { Card, CardHeader, Table, Btn, Badge, Modal, FormRow, FormField, Spinner } from '../components/ui/Card';
import api from '../utils/api';
import toast from 'react-hot-toast';
import { useAuth } from '../contexts/AuthContext';
import { useLang } from '../i18n/LanguageContext';

const TYPES_ABSENCE_FR = ['Congé annuel','Congé maladie','Congé maternité/paternité','Congé sans solde','Permission spéciale'];
const TYPES_ABSENCE_EN = ['Annual leave','Sick leave','Maternity/paternity leave','Unpaid leave','Special permission'];
const QUOTA_ANNUEL = 30;

function calculerJours(dateDebut, dateFin) {
  if (!dateDebut || !dateFin) return 0;
  const d1 = new Date(dateDebut), d2 = new Date(dateFin);
  if (d2 < d1) return 0;
  let count = 0;
  const cur = new Date(d1);
  while (cur <= d2) {
    const day = cur.getDay();
    if (day !== 0 && day !== 6) count++;
    cur.setDate(cur.getDate() + 1);
  }
  return count;
}

function CongeJauge({ pris, quota = QUOTA_ANNUEL, t }) {
  const reste = Math.max(0, quota - pris);
  const pct   = Math.min(100, (pris / quota) * 100);
  const color = pct >= 100 ? '#dc2626' : pct >= 80 ? '#f59e0b' : '#16a34a';
  return (
    <div style={{ minWidth:160 }}>
      <div style={{ display:'flex', justifyContent:'space-between', fontSize:'0.72rem', marginBottom:3, fontWeight:600 }}>
        <span style={{ color:'var(--gray-500)' }}>{t('absences.taken')}</span>
        <span style={{ color }}>{pris} / {quota} j</span>
      </div>
      <div style={{ height:7, background:'var(--gray-200)', borderRadius:99, overflow:'hidden' }}>
        <div style={{ height:'100%', width:`${pct}%`, background:color, borderRadius:99, transition:'width 0.4s' }} />
      </div>
      <div style={{ fontSize:'0.68rem', marginTop:3, color: reste===0 ? '#dc2626' : 'var(--gray-400)', fontWeight: reste===0 ? 700 : 400 }}>
        {reste === 0 ? t('absences.exhausted') : `${reste} ${t('absences.remaining')}`}
      </div>
    </div>
  );
}

export default function AbsencesPage() {
  const { hasRole } = useAuth();
  const { t, lang } = useLang();
  const [absences,  setAbsences]  = useState([]);
  const [personnel, setPersonnel] = useState([]);
  const [loading,   setLoading]   = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [form, setForm] = useState({ personnel_id:'', type:'Congé annuel', date_debut:'', date_fin:'', motif:'' });
  const [saving, setSaving] = useState(false);
  const [filterStatut, setFilterStatut] = useState('');
  const [filterPersonnel, setFilterPersonnel] = useState('');

  const TYPES = lang === 'en' ? TYPES_ABSENCE_EN : TYPES_ABSENCE_FR;
  const canApprove = hasRole('super_admin','assistant_admin','direction');

  useEffect(() => {
    const el = document.getElementById('page-title');
    if (el) el.textContent = t('absences.title');
    loadData();
  }, [lang]);

  const loadData = async () => {
    setLoading(true);
    try {
      const [a, p] = await Promise.all([api.get('/absences'), api.get('/personnel')]);
      setAbsences(a.data.data);
      setPersonnel(p.data.data);
    } catch { toast.error(t('common.error')); }
    finally { setLoading(false); }
  };

  const congesParPersonnel = useMemo(() => {
    const map = {};
    absences.forEach(a => {
      const typeIsAnnuel = a.type === 'Congé annuel' || a.type === 'Annual leave';
      if (typeIsAnnuel && a.statut === 'approuvé') {
        const pid = a.personnel_id || a.personnelId;
        if (!map[pid]) map[pid] = 0;
        map[pid] += calculerJours(a.date_debut, a.date_fin);
      }
    });
    return map;
  }, [absences]);

  const joursForm = useMemo(() => calculerJours(form.date_debut, form.date_fin), [form.date_debut, form.date_fin]);

  const typeIsAnnuel = form.type === 'Congé annuel' || form.type === 'Annual leave';

  const resteSelectionne = useMemo(() => {
    if (!form.personnel_id || !typeIsAnnuel) return null;
    const pris = congesParPersonnel[form.personnel_id] || 0;
    return QUOTA_ANNUEL - pris;
  }, [form.personnel_id, form.type, congesParPersonnel]);

  const quotaDepasse = resteSelectionne !== null && joursForm > resteSelectionne;

  const filtered = absences.filter(a => {
    const matchStatut = !filterStatut || a.statut === filterStatut;
    const matchPerso  = !filterPersonnel || String(a.personnel_id || a.personnelId) === filterPersonnel;
    return matchStatut && matchPerso;
  });

  const handleCreate = async e => {
    e.preventDefault();
    if (quotaDepasse) { toast.error(`${t('absences.quotaExceeded')} — ${resteSelectionne} j.`); return; }
    setSaving(true);
    try {
      await api.post('/absences', form);
      toast.success(t('common.success'));
      setModalOpen(false);
      loadData();
    } catch (err) { toast.error(err.response?.data?.message || t('common.error')); }
    finally { setSaving(false); }
  };

  const handleValidate = async (id, statut) => {
    try { await api.put(`/absences/${id}`, { statut }); toast.success(t('common.success')); loadData(); }
    catch { toast.error(t('common.error')); }
  };

  const openModal = () => {
    setForm({ personnel_id:'', type:TYPES[0], date_debut:'', date_fin:'', motif:'' });
    setModalOpen(true);
  };

  const statsBadge = statut => {
    const m = { en_attente:'warning', 'approuvé':'success', 'refusé':'error' };
    const label = { en_attente: lang==='en'?'pending':'en attente', 'approuvé': lang==='en'?'approved':'approuvé', 'refusé': lang==='en'?'refused':'refusé' };
    return <Badge type={m[statut]||'default'}>{label[statut]||statut}</Badge>;
  };

  const stats = {
    total:      absences.length,
    en_attente: absences.filter(a => a.statut === 'en_attente').length,
    approuves:  absences.filter(a => a.statut === 'approuvé').length,
    refuses:    absences.filter(a => a.statut === 'refusé').length,
    jours_pris: Object.values(congesParPersonnel).reduce((s,v) => s+v, 0),
  };

  const columns = [
    { key:'personnel_nom', header:t('absences.staffMember'), render:(v,row) => {
      const pid = row.personnel_id || row.personnelId;
      const pris = congesParPersonnel[pid] || 0;
      const isAnnuel = row.type === 'Congé annuel' || row.type === 'Annual leave';
      const perso = personnel.find(p => p.id === pid);
      return (
        <div>
          <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:isAnnuel?6:0 }}>
            {perso?.photo && (
              <div style={{ width:28, height:28, borderRadius:'50%', overflow:'hidden', border:'1.5px solid var(--gray-200)', flexShrink:0 }}>
                <img src={perso.photo} alt={perso.prenom} style={{ width:'100%', height:'100%', objectFit:'cover' }} />
              </div>
            )}
            <p style={{ fontWeight:600, color:'var(--navy)', fontSize:'0.87rem' }}>{v || '—'}</p>
          </div>
          {isAnnuel && <CongeJauge pris={pris} t={t} />}
        </div>
      );
    }},
    { key:'type', header:t('absences.type'), render:v => <Badge type={v==='Congé annuel'||v==='Annual leave'?'gold':'info'}>{v}</Badge> },
    { key:'date_debut', header:t('absences.startDate'), render:v => v ? new Date(v).toLocaleDateString(lang==='fr'?'fr-FR':'en-GB') : '—' },
    { key:'date_fin',   header:t('absences.endDate'),   render:v => v ? new Date(v).toLocaleDateString(lang==='fr'?'fr-FR':'en-GB') : '—' },
    { key:'date_debut', header:t('absences.duration'), render:(_,row) => {
      const j = calculerJours(row.date_debut, row.date_fin);
      return <span style={{ fontWeight:700, color:'var(--navy)' }}>{j} {lang==='fr'?'j.':'d.'}</span>;
    }},
    { key:'motif', header:t('absences.motif'), render:v => <span style={{ fontSize:'0.82rem', color:'var(--gray-500)' }}>{v||'—'}</span> },
    { key:'statut', header:t('common.status'), render:v => statsBadge(v) },
    { key:'actions', header:t('common.actions'), render:(_,row) => (
      <div style={{ display:'flex', gap:6 }}>
        {canApprove && row.statut === 'en_attente' && <>
          <Btn size="sm" variant="success" onClick={() => handleValidate(row.id,'approuvé')}>✅</Btn>
          <Btn size="sm" variant="danger"  onClick={() => handleValidate(row.id,'refusé')}>❌</Btn>
        </>}
      </div>
    )},
  ];

  return (
    <div className="animate-fade">

      {/* ── KPI CARDS ── */}
      <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit,minmax(140px,1fr))', gap:14, marginBottom:20 }}>
        {[
          { label:t('absences.kpi.total'),    value:stats.total,      color:'var(--navy)',    icon:'📋' },
          { label:t('absences.kpi.pending'),   value:stats.en_attente, color:'#f59e0b',        icon:'⏳' },
          { label:t('absences.kpi.approved'),  value:stats.approuves,  color:'var(--emerald)', icon:'✅' },
          { label:t('absences.kpi.refused'),   value:stats.refuses,    color:'var(--red)',     icon:'❌' },
          { label:t('absences.kpi.daysTaken'), value:stats.jours_pris, color:'#7c3aed',       icon:'📅' },
        ].map(s => (
          <div key={s.label} style={{ background:'white', borderRadius:'var(--radius)', boxShadow:'var(--shadow)', padding:'16px 18px', borderLeft:`4px solid ${s.color}` }}>
            <p style={{ fontSize:'0.72rem', color:'var(--gray-500)', textTransform:'uppercase', letterSpacing:'0.05em', marginBottom:4 }}>{s.icon} {s.label}</p>
            <p style={{ fontSize:'1.9rem', fontWeight:700, color:s.color, lineHeight:1 }}>{s.value}</p>
          </div>
        ))}
      </div>

      {/* ── QUOTA PAR PERSONNEL ── */}
      {personnel.length > 0 && (
        <Card style={{ marginBottom:20 }}>
          <CardHeader title={t('absences.tracking')} subtitle={`${t('absences.quota')} : ${QUOTA_ANNUEL} ${t('absences.daysPerYear')}`} />
          <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(220px,1fr))', gap:12 }}>
            {personnel.filter(p => p.statut === 'actif').map(p => {
              const pris  = congesParPersonnel[p.id] || 0;
              const reste = Math.max(0, QUOTA_ANNUEL - pris);
              const pct   = Math.min(100, (pris / QUOTA_ANNUEL) * 100);
              const color = pct >= 100 ? '#dc2626' : pct >= 80 ? '#f59e0b' : '#16a34a';
              return (
                <div key={p.id} style={{ border:`1px solid ${pct>=100?'#fca5a5':pct>=80?'#fde68a':'var(--gray-200)'}`, borderRadius:10, padding:'12px 14px', background:'white', borderLeft:`4px solid ${color}` }}>
                  <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:10 }}>
                    <div style={{ width:36, height:36, borderRadius:'50%', overflow:'hidden', border:'1.5px solid var(--gray-200)', background:'var(--gray-100)', display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 }}>
                      {p.photo ? <img src={p.photo} alt={p.prenom} style={{ width:'100%', height:'100%', objectFit:'cover' }} /> : <span style={{ fontSize:'1rem' }}>👤</span>}
                    </div>
                    <div style={{ overflow:'hidden' }}>
                      <p style={{ fontWeight:600, color:'var(--navy)', fontSize:'0.83rem', whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{p.prenom} {p.nom}</p>
                      <p style={{ fontSize:'0.7rem', color:'var(--gray-400)' }}>{p.poste}</p>
                    </div>
                  </div>
                  <div style={{ display:'flex', justifyContent:'space-between', fontSize:'0.72rem', marginBottom:5 }}>
                    <span style={{ color:'var(--gray-500)' }}>{pris} {t('absences.taken')}</span>
                    <span style={{ color, fontWeight:700 }}>{reste} {t('absences.remaining')}</span>
                  </div>
                  <div style={{ height:8, background:'var(--gray-200)', borderRadius:99, overflow:'hidden' }}>
                    <div style={{ height:'100%', width:`${pct}%`, background:color, borderRadius:99, transition:'width 0.5s' }} />
                  </div>
                  {pct >= 100 && <p style={{ fontSize:'0.68rem', color:'#dc2626', fontWeight:700, marginTop:5 }}>{t('absences.exhausted')}</p>}
                  {pct >= 80 && pct < 100 && <p style={{ fontSize:'0.68rem', color:'#d97706', fontWeight:600, marginTop:5 }}>⚠️ {lang==='fr'?'Quota presque épuisé':'Quota almost exhausted'}</p>}
                </div>
              );
            })}
          </div>
        </Card>
      )}

      {/* ── TABLEAU ── */}
      <Card>
        <CardHeader
          title={t('absences.requests')}
          subtitle={t('absences.history')}
          action={
            <div style={{ display:'flex', gap:10, flexWrap:'wrap' }}>
              <select value={filterPersonnel} onChange={e => setFilterPersonnel(e.target.value)} style={{ width:'auto', minWidth:160 }}>
                <option value="">{t('common.allStaff')}</option>
                {personnel.map(p => <option key={p.id} value={p.id}>{p.prenom} {p.nom}</option>)}
              </select>
              <select value={filterStatut} onChange={e => setFilterStatut(e.target.value)} style={{ width:'auto' }}>
                <option value="">{t('common.allStatuses')}</option>
                <option value="en_attente">{t('absences.statuses.pending')}</option>
                <option value="approuvé">{t('absences.statuses.approved')}</option>
                <option value="refusé">{t('absences.statuses.refused')}</option>
              </select>
              <Btn variant="gold" onClick={openModal}>{t('absences.newRequest')}</Btn>
            </div>
          }
        />
        {loading ? <Spinner /> : <Table columns={columns} data={filtered} emptyMessage={lang==='fr'?"Aucune demande d'absence":"No absence requests"} />}
      </Card>

      {/* ── MODAL ── */}
      <Modal open={modalOpen} onClose={() => setModalOpen(false)} title={t('absences.newRequest').replace('➕ ','')}>
        <form onSubmit={handleCreate} style={{ padding:24 }}>

          <FormRow cols={1}>
            <FormField label={`${t('absences.staffMember')} *`} required>
              <select value={form.personnel_id} onChange={e => setForm({...form, personnel_id:e.target.value})} required>
                <option value="">{t('absences.selectStaff')}</option>
                {personnel.map(p => {
                  const pris  = congesParPersonnel[p.id] || 0;
                  const reste = QUOTA_ANNUEL - pris;
                  const tag   = reste <= 0 ? ` ⛔ ${t('absences.quotaTag')}` : reste <= 5 ? ` (${reste}j)` : '';
                  return <option key={p.id} value={p.id}>{p.prenom} {p.nom} — {p.poste}{tag}</option>;
                })}
              </select>
            </FormField>
          </FormRow>

          {/* Quota gauge */}
          {form.personnel_id && typeIsAnnuel && (
            <div style={{ background: resteSelectionne <= 0 ? '#fef2f2' : '#f0fdf4', border:`1px solid ${resteSelectionne <= 0 ? '#fca5a5' : '#86efac'}`, borderRadius:10, padding:'12px 16px', marginBottom:16 }}>
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8 }}>
                <p style={{ fontSize:'0.8rem', fontWeight:700, color: resteSelectionne <= 0 ? '#dc2626' : '#166534' }}>
                  {resteSelectionne <= 0 ? t('absences.quotaExhausted') : `📅 ${t('absences.quotaInfo')}`}
                </p>
                <span style={{ fontSize:'0.85rem', fontWeight:700, color: resteSelectionne <= 0 ? '#dc2626' : '#166534' }}>
                  {Math.max(0, resteSelectionne)} / {QUOTA_ANNUEL} {t('absences.quotaRemaining')}
                </span>
              </div>
              <div style={{ height:10, background:'#e5e7eb', borderRadius:99, overflow:'hidden' }}>
                <div style={{ height:'100%', width:`${Math.min(100, ((QUOTA_ANNUEL-Math.max(0,resteSelectionne))/QUOTA_ANNUEL)*100)}%`, background: resteSelectionne<=0 ? '#dc2626' : resteSelectionne<=5 ? '#f59e0b' : '#16a34a', borderRadius:99 }} />
              </div>
              {joursForm > 0 && (
                <p style={{ fontSize:'0.75rem', marginTop:8, color: quotaDepasse ? '#dc2626' : '#166534', fontWeight:600 }}>
                  {quotaDepasse
                    ? `❌ ${t('absences.usesdays')} ${joursForm} j. — ${t('absences.exceeds')} (${resteSelectionne} j.)`
                    : `✅ ${t('absences.usesdays')} ${joursForm} j. — ${t('absences.willRemain')} ${resteSelectionne - joursForm} j.`}
                </p>
              )}
            </div>
          )}

          <FormRow cols={1}>
            <FormField label={t('absences.type')}>
              <select value={form.type} onChange={e => setForm({...form, type:e.target.value})}>
                {TYPES.map(ty => <option key={ty}>{ty}</option>)}
              </select>
            </FormField>
          </FormRow>

          <FormRow>
            <FormField label={`${t('absences.startDate')} *`}><input type="date" value={form.date_debut} onChange={e => setForm({...form, date_debut:e.target.value})} required /></FormField>
            <FormField label={`${t('absences.endDate')} *`}><input type="date" value={form.date_fin} onChange={e => setForm({...form, date_fin:e.target.value})} required /></FormField>
          </FormRow>

          {joursForm > 0 && (
            <div style={{ background:'var(--gray-50)', border:'1px solid var(--gray-200)', borderRadius:8, padding:'8px 14px', marginBottom:14, display:'flex', gap:8, alignItems:'center' }}>
              <span style={{ fontSize:'0.8rem', color:'var(--gray-500)' }}>{t('absences.workDays')}</span>
              <span style={{ fontWeight:700, color:'var(--navy)', fontSize:'0.9rem' }}>{joursForm} {t('absences.days')}</span>
            </div>
          )}

          <FormRow cols={1}>
            <FormField label={t('absences.motif')}>
              <textarea value={form.motif} onChange={e => setForm({...form, motif:e.target.value})} rows={3} style={{ resize:'vertical' }} />
            </FormField>
          </FormRow>

          <div style={{ display:'flex', gap:10, justifyContent:'flex-end' }}>
            <Btn type="button" variant="secondary" onClick={() => setModalOpen(false)}>{t('common.cancel')}</Btn>
            <Btn type="submit" variant="gold" disabled={saving || quotaDepasse}>
              {saving ? t('common.sending') : quotaDepasse ? t('absences.quotaExceeded') : t('absences.submit')}
            </Btn>
          </div>
        </form>
      </Modal>
    </div>
  );
}
